from __future__ import annotations

__doc__ = """Python wrapper layer for generated NumPy-backed libraries."""

from ..pywrapper_library import PyWrapperLibraryBase, WrapperBase


class NumPyWrapper(WrapperBase):
    """Wrapper for generated NumPy-based routines."""


class NumPyPyWrapperLibrary(PyWrapperLibraryBase):
    """Python wrapper library for generated NumPy-backed libraries."""

    WRAPPER_CLASS = NumPyWrapper

    def resolve_wrapper_callable(self, libroutine_name, _libroutine):
        return getattr(self.wrapper_lib, libroutine_name)
